import jakarta.persistence.*;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="sales_surcharge_reason") public class MotivoRecargoVenta {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="name",nullable=false)private String nombre;@Column(name="normalized_name",nullable=false)private String nombreNormalizado;@Column(name="other_reason",nullable=false)private boolean otro;@Column(nullable=false)private boolean active=true;@Column(name="created_at",insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",updatable=false)private UUID creadoPor;@Column(name="updated_at")private OffsetDateTime actualizadoEn;@Column(name="updated_by")private UUID actualizadoPor;@Version private long version;protected MotivoRecargoVenta(){}public MotivoRecargoVenta(UUID t,UUID e,String n,String nn,boolean o,UUID u){tenantId=t;empresaId=e;nombre=n;nombreNormalizado=nn;otro=o;creadoPor=u;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public void actualizar(String n,String nn,boolean o,boolean a,UUID u){nombre=n;nombreNormalizado=nn;otro=o;active=a;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public UUID getId(){return id;}public String getNombre(){return nombre;}public boolean isOtro(){return otro;}public boolean isActivo(){return active;}public long getVersion(){return version;}}
